        );
        CREATE TABLE IF NOT EXISTS audit_log (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER,
            action TEXT NOT NULL,
            detail TEXT,
            created_at TEXT NOT NULL
        );
        """
    )
    conn.commit()
    return conn


# ---------------------------------------------------------------------------
# 入口（仅本地脚本演示，不暴露 HTTP）
